.untie .bp.tr{animation:tailR 1.5s cubic-bezier(.5,0,.6,1) .08s forwards}
@keyframes knotUndo{0%{transform:scale(1)}25%{transform:scale(1.5) rotate(-8deg)}60%{transform:scale(1.1) rotate(14deg);opacity:1}100%{transform:scale(.2) rotate(45deg);opacity:0}}
@keyframes loopL{0%{transform:scale(1)}30%{transform:scale(1.04,1.06) rotate(-3deg)}70%{transform:scale(.45,.6) rotate(-12deg);opacity:1}100%{transform:scale(.05,.4) rotate(-24deg);opacity:0}}
@keyframes loopR{0%{transform:scale(1)}30%{transform:scale(1.04,1.06) rotate(3deg)}70%{transform:scale(.45,.6) rotate(12deg);opacity:1}100%{transform:scale(.05,.4) rotate(24deg);opacity:0}}
@keyframes tailL{0%{transform:rotate(0)}30%{transform:rotate(-5deg) translateY(-2%)}100%{transform:rotate(16deg) translate(-12%,60%);opacity:0}}
@keyframes tailR{0%{transform:rotate(0)}30%{transform:rotate(5deg) translateY(-2%)}100%{transform:rotate(-16deg) translate(12%,60%);opacity:0}}
#env-card{position:absolute;z-index:2;left:50%;top:calc(50% + var(--oy));width:var(--cw);height:calc(var(--cw)/.72);
  margin:calc(var(--cw)/-1.44) 0 0 calc(var(--cw)/-2);transform:translateY(0) scale(var(--s0));
  background:var(--cinder) center/cover,#e9f0fb;box-shadow:0 10px 30px rgba(50,80,130,.25);
  transition:transform 1.3s cubic-bezier(.3,.75,.25,1),box-shadow 1.2s}
#env-card p{position:absolute;inset:0;margin:0;display:flex;align-items:center;justify-content:center;text-align:center;
  font:400 calc(var(--cw)*.135)/1.28 "Great Vibes","Pinyon Script",cursive;color:#5b82b4;padding-top:2%}
.opening .flap{transform:rotateX(180deg)}
.opening .fl{z-index:1}
.rise #env-card{transform:translateY(var(--y1)) scale(var(--s1))}
.show #env-card{z-index:6;transform:translateY(calc(var(--oy)*-1)) scale(1);box-shadow:0 22px 50px rgba(50,80,130,.32);
  transition:transform 1.6s cubic-bezier(.65,0,.25,1),box-shadow 1.4s}
.show .lay{transform:translateY(16%) scale(.94);opacity:0}
.show #env-title{opacity:0}
.untie [class*="top-[24%]"]{opacity:0!important;transition:opacity .4s}
[class*="top-[24%]"]{top:auto!important;bottom:calc(5% + env(safe-area-inset-bottom,0px))!important}
#fall{position:absolute;inset:0;z-index:8;pointer-events:none;overflow:hidden}
.tw{position:absolute;width:10px;height:10px;opacity:0;animation:tw 3.2s ease-in-out infinite}
.tw::before,.tw::after{content:"";position:absolute;left:50%;top:50%;background:#fff;box-shadow:0 0 6px 1px rgba(255,255,255,.9);border-radius:2px}
.tw::before{width:2px;height:10px;margin:-5px 0 0 -1px}.tw::after{width:10px;height:2px;margin:-1px 0 0 -5px}
@keyframes tw{0%,100%{opacity:0;transform:scale(.3) rotate(0)}50%{opacity:.95;transform:scale(1) rotate(45deg)}}

.splash-out{opacity:0;pointer-events:none;transition:opacity 1s ease .15s}
.photo-frame{height:auto!important;width:fit-content!important;max-width:100%;margin-inline:auto;display:flex}
.photo-img{position:static!important;display:block;width:auto!important;height:auto!important;max-width:100%!important;max-height:min(78vh,900px);object-fit:contain}
section.min-h-screen>img{object-position:8% 22%}
@media (min-aspect-ratio:3/4){section.min-h-screen>img{object-position:50% 24%}}
section.min-h-screen>.bg-black\/40{background:linear-gradient(to bottom,rgba(0,0,0,.1) 0%,rgba(0,0,0,.14) 32%,rgba(0,0,0,.4) 58%,rgba(0,0,0,.56) 100%)!important}
@media (orientation:portrait) and (min-width:640px){section.min-h-screen .my-auto{--tw-translate-y:14rem!important}}
#mapcard{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;
  text-decoration:none;color:#fff;text-align:center;padding:20px;
  background:linear-gradient(135deg,rgba(61,143,198,.92),rgba(134,197,234,.85))}
#mapcard span{font:600 1.4rem "Playfair Display",serif}
#mapcard small{letter-spacing:.3em;text-transform:uppercase;font-weight:900;font-size:10px}
.reveal-in{opacity:1!important;transform:none!important;transition:opacity .9s ease,transform .9s ease}
.slides-track{transition:transform .8s cubic-bezier(.22,.8,.3,1)}
#toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);
  background:#3D8FC6;color:#fff;padding:10px 18px;border-radius:999px;font:700 12px Outfit,sans-serif;
  letter-spacing:.1em;z-index:400;opacity:0;pointer-events:none;transition:opacity .3s}
#toast.on{opacity:1}

/* carruseles: todas las fotos con el mismo tamaño; la foto se adapta al marco */
.slides-track .photo-frame{display:block!important;width:min(100%,440px,calc(80vh*.75))!important;aspect-ratio:3/4;height:auto!important;max-width:100%}
.slides-track .photo-img{position:absolute!important;inset:0;width:100%!important;height:100%!important;max-width:none!important;max-height:none!important;object-fit:cover!important;object-position:50% 30%}
.slides-track img[alt="Silvia de niña 1"]{object-position:56% 40%}
.slides-track img[alt="Silvia de niña 2"],.slides-track img[alt="Silvia de niña 3"]{object-position:50% 36%}
.slides-track img[alt="Silvia 1"]{object-position:50% 35%!important}
.slides-track img[alt="Silvia 2"]{object-position:50% 25%!important}
.slides-track img[alt="Silvia 3"],.slides-track img[alt="Silvia 4"]{object-position:50% 100%!important}

#music-btn{position:fixed;right:14px;top:calc(14px + env(safe-area-inset-top,0px));z-index:300;width:42px;height:42px;border-radius:50%;
  display:none;align-items:center;justify-content:center;color:#fff;background:rgba(61,143,198,.85);border:1px solid rgba(255,255,255,.5);
  box-shadow:0 4px 14px rgba(0,0,0,.25);backdrop-filter:blur(6px);cursor:pointer}
#music-btn.on{display:flex}
#music-btn .ic-off{display:none}#music-btn.muted .ic-on{display:none}#music-btn.muted .ic-off{display:block}
